using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{public void Execute(ExecutionResult result){var s=SceneManager.GetActiveScene();foreach(var r in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.enabled&&r.name.Contains("island_tree_02")).Take(1)){var f=r.GetComponent<MeshFilter>();result.Log("CURRENT "+r.transform.parent.name+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+" subs="+f.sharedMesh.subMeshCount+" mats="+string.Join(";",r.sharedMaterials.Select(m=>AssetDatabase.GetAssetPath(m))));}var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Environment/FinalWorldVegetation/island_tree_02.prefab");foreach(var r in p.GetComponentsInChildren<Renderer>(true)){var f=r.GetComponent<MeshFilter>();result.Log("APPROVED "+r.name+" enabled="+r.enabled+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+" mats="+string.Join(";",r.sharedMaterials.Select(m=>AssetDatabase.GetAssetPath(m))));}}}
